mapper.select:
select score
from team_rating
where match_id = #{matchId}
  and team_id = #{targetTeamId}
  and evaluator_user_id = #{userId}
limit 1

mapper.update:
update team_rating
set score = #{score}, created_at = now()
where match_id = #{matchId}
  and team_id = #{targetTeamId}
  and evaluator_user_id = #{userId}
